import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'

import { getCurrentTeamId } from '~/lib/utils/getAppContext'

import { precomputeDebugInvalidate, precomputeDebugState } from './generated/api'
import type { PrecomputeDebugResponseApi } from './generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface precomputeDebugLogicValues {
    debugState: PrecomputeDebugResponseApi | null
    debugStateLoading: boolean
    invalidatingHash: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface precomputeDebugLogicActions {
    invalidate: (queryHash: string | null) => {
        queryHash: string | null
    }
    invalidateFinished: () => {
        value: true
    }
    loadDebugState: () => any
    loadDebugStateFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDebugStateSuccess: (
        debugState: PrecomputeDebugResponseApi,
        payload?: any
    ) => {
        debugState: PrecomputeDebugResponseApi
        payload?: any
    }
}

export type precomputeDebugLogicType = MakeLogicType<precomputeDebugLogicValues, precomputeDebugLogicActions>

export const precomputeDebugLogic = kea<precomputeDebugLogicType>([
    path(['products', 'analytics_platform', 'frontend', 'precomputeDebugLogic']),

    actions({
        invalidate: (queryHash: string | null) => ({ queryHash }),
        invalidateFinished: true,
    }),

    loaders({
        debugState: [
            null as PrecomputeDebugResponseApi | null,
            {
                loadDebugState: async () => {
                    return await precomputeDebugState(String(getCurrentTeamId()))
                },
            },
        ],
    }),

    reducers({
        // The hash being invalidated, or 'all' — drives per-button loading and
        // blocks concurrent invalidations.
        invalidatingHash: [
            null as string | null,
            {
                invalidate: (_, { queryHash }) => queryHash ?? 'all',
                invalidateFinished: () => null,
            },
        ],
    }),

    listeners(({ actions }) => ({
        invalidate: async ({ queryHash }) => {
            try {
                const result = await precomputeDebugInvalidate(String(getCurrentTeamId()), {
                    query_hash: queryHash,
                })
                lemonToast.success(
                    `Marked ${result.updated_count} precompute ${result.updated_count === 1 ? 'job' : 'jobs'} stale`
                )
                actions.loadDebugState()
            } catch {
                lemonToast.error('Failed to invalidate precompute jobs')
            } finally {
                actions.invalidateFinished()
            }
        },
    })),

    afterMount(({ actions }) => {
        actions.loadDebugState()
    }),
])
